StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_MotorControl                                                                                                                                                                                                                                                                        
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE					SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-03-04			William Veim			Initial release              
//	1.0.1				2025-11-12			William Veim			Bugfix visibility step mode
//	1.0.2				2025-11-17			William Veim			Added limitation of minimum and maximum number of running
//	1.0.3				2026-03-13			William Veim			Added logic for reatining output after state active
//	1.0.4				2026-04-13			William Veim			Bugfix step in / out according to action state 
//==============================================================================================================================
//
// 		FUNCTIONALITY:
// 		* PID Controller
// 		* Operates converters based on status (online, ready, fault-free, and no interlocks) as follows:
//   	- Keeps at least one converter running at all times
//   	- Steps converters in/out based on threshold values and delays set in SCADA
//   	- Alternates operation on the selected weekday and time
// 		* Operation modes:
//   	- OFF      → Common output control = 0
//   	- AUTO     → Common output follows regulation control
// 		* Automatic switch of process value sensor upon digital alarm (failure) detection. Can be overridden in SCADA.
// 		* Stops operation if an interlock condition is detected.
//
//==============================================================================================================================

CurrentTime := TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)
 
Ext_MultiControl.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_MultiControl.EXT_Alarm.Sts_SupressIfOff_Visible:=					TRUE;
Ext_MultiControl.EXT_General.Controlled_FromController:=			Cfg_ControllerName;
Ext_MultiControl.EXT_General.MultiControl_Cofig_Visible:= 			Cfg_Mode; 

IF NOT Cfg_Mode THEN
	Ext_MultiControl.EXT_Engineering.Alternation_Visible:=FALSE;
	Ext_MultiControl.EXT_Engineering.StepMode_Visible:=FALSE;
END_IF;

 IF NOT Ext_MultiControl.INT_Data.Initialise THEN
	
	//Engeneering settings
	Ext_MultiControl.EXT_Engineering.Delay_StepIn:=30;
	Ext_MultiControl.EXT_Engineering.Delay_StepOut:=30;	
	Ext_MultiControl.EXT_Engineering.Limit_StepIn:=80;
	Ext_MultiControl.EXT_Engineering.Limit_StepOut:=20;
	Ext_MultiControl.EXT_Engineering.PID_P_Band:=20;
	Ext_MultiControl.EXT_Engineering.PID_I_Tid:=50;
	Ext_MultiControl.EXT_Engineering.PID_D_Tid:=0;
	Ext_MultiControl.EXT_Engineering.Alternation_Clock_Hour:=12;
	Ext_MultiControl.EXT_Engineering.Alternation_Clock_Minute:=00;
	Ext_MultiControl.EXT_Engineering.Step_MinimumCount:=1;
	Ext_MultiControl.EXT_Engineering.Step_MaximumCount:=1;
	Ext_MultiControl.EXT_Engineering.Step_ManualCount:=1;
	
	//State config
	Ext_MultiControl.EXT_Engineering.StateCfg_1.Cfg_Quality:=3; //Process value not available = Warning
	Ext_MultiControl.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Process value not available = Alarm
	Ext_MultiControl.EXT_Engineering.StateCfg_2.Cfg_Quality:=0; //Configuration fault = Diagnostic
	Ext_MultiControl.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; //Configuration fault = Alarm
	Ext_MultiControl.EXT_Engineering.StateCfg_3.Cfg_Quality:=0; //No actuator ready = Warning
	Ext_MultiControl.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; //No actuator ready = Alarm
	
	//Alarm settings
	Ext_MultiControl.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_MultiControl.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_MultiControl.EXT_Alarm.Cfg_AlarmReturnDelay:=10;
	
	//Init complete
	Ext_MultiControl.INT_Data.Initialise:=TRUE;
	
END_IF;

(*************************************************************************
 *	UPDATING SETPOINT VALUE VALUE
 *************************************************************************)

FB_SP_AutoSwitch1(ENS:=TRUE, 
								Ext_AnalogValue:=Ext_AnalogValue, 
								Inp_SetpointData:=Ext_MultiControl.EXT_Engineering.Cfg_SP_Data1, 
								Inp_CustomTrigger:=Inp_SP1_AutoSwitchTrig_Custom, 
								Inp_CustomTrigger_Suffix:=Cfg_SP1_AutoSwitchSuffix_Custom);

FB_SP_AutoSwitch2(ENS:=TRUE, 
								Ext_AnalogValue:=Ext_AnalogValue, 
								Inp_SetpointData:=Ext_MultiControl.EXT_Engineering.Cfg_SP_Data2, 
								Inp_CustomTrigger:=Inp_SP2_AutoSwitchTrig_Custom, 
								Inp_CustomTrigger_Suffix:=Cfg_SP2_AutoSwitchSuffix_Custom);

FB_SP_AutoSwitch3(ENS:=TRUE, 
								Ext_AnalogValue:=Ext_AnalogValue, 
								Inp_SetpointData:=Ext_MultiControl.EXT_Engineering.Cfg_SP_Data3, 
								Inp_CustomTrigger:=Inp_SP3_AutoSwitchTrig_Custom, 
								Inp_CustomTrigger_Suffix:=Cfg_SP3_AutoSwitchSuffix_Custom);

FB_SP_AutoSwitch4(ENS:=TRUE, 
								Ext_AnalogValue:=Ext_AnalogValue, 
								Inp_SetpointData:=Ext_MultiControl.EXT_Engineering.Cfg_SP_Data4, 
								Inp_CustomTrigger:=Inp_SP4_AutoSwitchTrig_Custom, 
								Inp_CustomTrigger_Suffix:=Cfg_SP4_AutoSwitchSuffix_Custom);

IF FB_SP_AutoSwitch1.Out_AutoSwitch THEN
	Ext_MultiControl.EXT_Operator.SP_Select:=1;
	Ext_MultiControl.EXT_General.SP_AutoSwitch_Excecuted:=TRUE;
ELSIF FB_SP_AutoSwitch2.Out_AutoSwitch THEN
	Ext_MultiControl.EXT_Operator.SP_Select:=2;
	Ext_MultiControl.EXT_General.SP_AutoSwitch_Excecuted:=TRUE;
ELSIF FB_SP_AutoSwitch3.Out_AutoSwitch THEN
	Ext_MultiControl.EXT_Operator.SP_Select:=3;
	Ext_MultiControl.EXT_General.SP_AutoSwitch_Excecuted:=TRUE;
ELSIF FB_SP_AutoSwitch4.Out_AutoSwitch THEN
	Ext_MultiControl.EXT_Operator.SP_Select:=4;
	Ext_MultiControl.EXT_General.SP_AutoSwitch_Excecuted:=TRUE;
ELSE
	IF Ext_MultiControl.EXT_Operator.SP_Select <> Wrk_Sample_SP AND Ext_MultiControl.EXT_General.SP_AutoSwitch_Excecuted THEN
		Ext_MultiControl.EXT_Operator.SP_Select := Wrk_Sample_SP;
	END_IF;
	Ext_MultiControl.EXT_General.SP_AutoSwitch_Excecuted:=FALSE;
	Wrk_Sample_SP := Ext_MultiControl.EXT_Operator.SP_Select;
END_IF;

HE_SP_Select(SP_Select:=Ext_MultiControl.EXT_Operator.SP_Select, 
					SP_Normal:=Ext_MultiControl.EXT_Operator.SP_Normal, 
					SP_Value1:=Ext_MultiControl.EXT_Engineering.Cfg_SP_Data1.SetpointValue, 
					SP_Value2:=Ext_MultiControl.EXT_Engineering.Cfg_SP_Data2.SetpointValue, 
					SP_Value3:=Ext_MultiControl.EXT_Engineering.Cfg_SP_Data3.SetpointValue, 
					SP_Value4:=Ext_MultiControl.EXT_Engineering.Cfg_SP_Data4.SetpointValue, 
					PV_Unit:=Ext_MultiControl.EXT_Operator.PV_Actual.Process_Unit, 
					SP_Actual:=Ext_MultiControl.EXT_Operator.SP_Actual, 
					SP_NumberUsed=>Wrk_NumberSPUsed, 
					SP_MultipleUsed=>Ext_MultiControl.EXT_General.SP_ValueChange_Visible);

(*************************************************************************
 *	UPDATING PID INPUT VALUES
 *************************************************************************)
 
HE_PV_Select(EXT_AnalogValue:=		Ext_AnalogValue, 
					 PV_Select:=						Ext_MultiControl.EXT_Operator.PV_Select, 
					 PV_AutoSwitch:=			Ext_MultiControl.EXT_Engineering.PV_AutoSwitch, 
					 PV_AutoSwitchState:=	Ext_MultiControl.EXT_Engineering.PV_AutoSwitchState, 
					 PV_Actual=>					Ext_MultiControl.EXT_Operator.PV_Actual, 
					 PV_Actual_Y0=>				Wrk_PV_Actual_Y0, 
					 PV_Actual_Y1=>				Wrk_PV_Actual_Y1, 
					 PV_NotAvailable=>		Wrk_PVNotAvailable, 
					 PV_NumberUsed=>		Wrk_NumberPVUsed, 
					 PV_MultipleUsed=>		Ext_MultiControl.EXT_General.PV_ValueChange_Visible, 
					 PV_Value1_Index:=			Ext_MultiControl.EXT_Engineering.Cfg_PV_Value1, 
					 PV_Value2_Index:=			Ext_MultiControl.EXT_Engineering.Cfg_PV_Value2, 
					 PV_Value3_Index:=			Ext_MultiControl.EXT_Engineering.Cfg_PV_Value3, 
					 PV_Value4_Index:=			Ext_MultiControl.EXT_Engineering.Cfg_PV_Value4, 
					 PV_Value5_Index:=			Ext_MultiControl.EXT_Engineering.Cfg_PV_Value5);

(*************************************************************************
 *	PID CONTROL
 *************************************************************************)
 
FB_PID(ENS:=									Ext_MultiControl.EXT_Operator.Mode = 2, 
			Cfg_RetainOutput:=				TRUE, 
			Inp_ManualControl:=			Wrk_ActionState=1 OR Wrk_ActionState=2 OR Wrk_NumberOfReady = 0, 
			Inp_ManualValue:=				Wrk_AutoOutput, 
			Inp_Proportional_Band:=		Ext_MultiControl.EXT_Engineering.PID_P_Band, 
			Inp_IntergrationTime:=		Ext_MultiControl.EXT_Engineering.PID_I_Tid, 
			Inp_DerivationTime:=			Ext_MultiControl.EXT_Engineering.PID_D_Tid, 
			ProcessValue:=					Ext_MultiControl.EXT_Operator.PV_Actual.ProcessValue, 
			SetpointValue:=					Ext_MultiControl.EXT_Operator.SP_Actual.ProcessValue, 
			Autotune_Start:=					Ext_MultiControl.EXT_Engineering.Autotune_Start, 
			RngUpLmt:=						Wrk_PV_Actual_Y1, 
			RngLowLmt:=						Wrk_PV_Actual_Y0, 
			MVLowLmt:=						0.0, 
			MVUpLmt:=							100.0, 
			Direction:=							Ext_MultiControl.EXT_Engineering.Direction, 
			Autotune_Done=>				Ext_MultiControl.EXT_Engineering.Autotune_Completed, 
			Autotune_Busy=>				Wrk_AutotuneOngoing, 
			Output=>							Wrk_AutoOutput);

(*************************************************************************
 *	STATE/FAULT CONTROL
 *************************************************************************)	

//FAULT CONTROL
//---------------------------
Wrk_AutoSwitch_Executed:=	Ext_MultiControl.EXT_General.SP_AutoSwitch_Excecuted;
Wrk_AutoSwitch_InUse:= 		FB_SP_AutoSwitch1.Sts_AutoSwitch_InUse OR FB_SP_AutoSwitch2.Sts_AutoSwitch_InUse OR FB_SP_AutoSwitch3.Sts_AutoSwitch_InUse OR FB_SP_AutoSwitch4.Sts_AutoSwitch_InUse;
Wrk_PVNotAvailable:=			Wrk_PVNotAvailable;
Wrk_NoActuatorReady:=			Wrk_NumberOfReady=0;
Wrk_ConfigFault:=					(Ext_MultiControl.EXT_Engineering.PID_P_Band=0 OR Ext_MultiControl.EXT_Engineering.PID_I_Tid = 0)
												OR (Ext_MultiControl.EXT_Engineering.StepMode_Visible AND Ext_MultiControl.EXT_Engineering.Step_MaximumCount<Ext_MultiControl.EXT_Engineering.Step_MinimumCount);

// STATE CONTROL
//------------------

//Resetter variabler før løkke
Ext_MultiControl.EXT_General.Sts_Quality :=  6; //Good
Wrk_ActionState:=	0;

//STATE 1 - Process value not available
HE_StateControl(EXT_StateData:=Ext_MultiControl.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_PVNotAvailable, 
							Inp_Desc:='Process value not available', 
							Sts_Quality:=Ext_MultiControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);
		
//STATE 2 - Configuration fault
HE_StateControl(EXT_StateData:=Ext_MultiControl.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_ConfigFault, 
							Inp_Desc:='Configuration fault', 
							Sts_Quality:=Ext_MultiControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//STATE 3 - No actuator ready
HE_StateControl(EXT_StateData:=Ext_MultiControl.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_NoActuatorReady, 
							Inp_Desc:='No actuator ready', 
							Sts_Quality:=Ext_MultiControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);

//STATE 4 - Auto switch SP executed
HE_StateControl(EXT_StateData:=Ext_MultiControl.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=Wrk_AutoSwitch_InUse, 
							Inp_State:=Wrk_AutoSwitch_Executed, 
							Inp_Desc:='Auto switch SP executed', 
							Sts_Quality:=Ext_MultiControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[3].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[3].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[3].Alm_Priority);

//STATE 5 - Spare
HE_StateControl(EXT_StateData:=Ext_MultiControl.EXT_Engineering.StateCfg_5, 
							Inp_Visibility:=FALSE, 
							Inp_State:=FALSE, 
							Inp_Desc:='', 
							Sts_Quality:=Ext_MultiControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[4].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[4].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[4].Alm_Priority);
		
CASE Wrk_ActionState OF
	
	0://Use value
	Ext_MultiControl.EXT_Operator.Actual_Output:= Wrk_Output;
	
	1://Hold value
	Ext_MultiControl.EXT_Operator.Actual_Output:=Ext_MultiControl.EXT_Operator.Actual_Output;
	
	2://Pre defined output
	Ext_MultiControl.EXT_Operator.Actual_Output:=Ext_MultiControl.EXT_Engineering.StateCfg_PreDefinedOutput;
	
	3://OFF
	Ext_MultiControl.EXT_Operator.Actual_Output:=0;
	
END_CASE;	

(*************************************************************************
 *	ALARM CONTROL
 *************************************************************************)

//Supress if off mode
IF Ext_MultiControl.EXT_Alarm.Sts_SupressIfOff_Visible AND Ext_MultiControl.EXT_Alarm.Cfg_SupressIfOff AND Ext_MultiControl.EXT_Operator.Mode = 0 THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= 'Off mode';
//Supress from FB input
ELSIF Inp_AlmSuppress THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= Inp_AlmSuppressDesc;
ELSE
	FB_AlarmLogic.Inp_AlarmSupress:=FALSE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= '';
END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_MultiControl.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_MultiControl.EXT_General.LocationIndex,
								 Inp_Connected_Cabinet:='', 
								 Inp_Connected_Controller:=Cfg_ControllerName, 
								 Inp_Process_TAG:='',
								 Inp_Process_Value:= '',
								 Inp_Process_Desc:=Ext_MultiControl.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered);

(*************************************************************************
 *	MODE CONTROL
 *************************************************************************)
 
CASE Ext_MultiControl.EXT_Operator.Mode OF
		
	    0://Off

				//Clar outpt
				//---------------
				Wrk_Output := 0;
				
				//Clear control data
				//--------------------------------
				Clear(Wrk_ActuatorEngage);
				
		2://Auto
		
				//Output control
				//-----------------
				TON_StartAuto(In:=Wrk_AutoOutput>0.5, PT:=SecToTime(Ext_MultiControl.EXT_Engineering.OutputStartDelay));
				
				IF TON_StartAuto.Q THEN //Pådrag må være over 0.5% i 5sek
					Wrk_Output := Wrk_AutoOutput;
				ELSE
					Wrk_Output := 0;
				END_IF;
				
				//Step mode in use
				IF Ext_MultiControl.EXT_Engineering.StepMode_Visible THEN
					
					//Conditions and control step in
					TON_StepIn.In :=Wrk_Output > Ext_MultiControl.EXT_Engineering.Limit_StepIn AND Wrk_NumberOfRunning < Ext_MultiControl.EXT_Engineering.Step_MaximumCount AND NOT TON_StepIn.Q;
					TON_StepIn(PT:=SecToTime(Ext_MultiControl.EXT_Engineering.Delay_StepIn));
					Wrk_StepIn:=TON_StepIn.Q OR Ext_MultiControl.EXT_Operator.Manual_StepIn;
					
					
					//Conditions and control step out
					TON_StepOut.In:= Wrk_Output < Ext_MultiControl.EXT_Engineering.Limit_StepOut AND Wrk_NumberOfRunning > Ext_MultiControl.EXT_Engineering.Step_MinimumCount AND NOT TON_StepOut.Q;
					TON_StepOut(PT:=SecToTime(Ext_MultiControl.EXT_Engineering.Delay_StepOut));
					Wrk_StepOut:=TON_StepOut.Q OR Ext_MultiControl.EXT_Operator.Manual_StepOut;
				
				//Step mode not in use
				ELSE 
					Ext_MultiControl.EXT_Engineering.Step_MinimumCount:=Ext_MultiControl.EXT_Engineering.Step_ManualCount;
					Ext_MultiControl.EXT_Engineering.Step_MaximumCount:=Ext_MultiControl.EXT_Engineering.Step_ManualCount;
				END_IF;
				
				//Force number of actuators if wrk_actionState = Custom/pre defined value
				IF Wrk_ActionState = 2 THEN
					IF Wrk_NumberOfRunning > Ext_MultiControl.EXT_Engineering.StateCfg_PreDefinedNumOfActuators THEN
						Wrk_StepOut := TRUE;
					
					ELSIF Wrk_NumberOfRunning < Ext_MultiControl.EXT_Engineering.StateCfg_PreDefinedNumOfActuators THEN
						Wrk_StepIn := TRUE;
					END_IF;
				END_IF;	
				
				//Kriterier for alternering
				//-------------------------
				
				//Sammenlikner dag og klokkeslett for alternering
				IF CurrentTime = HE_INT2TOD(Hour:=Ext_MultiControl.EXT_Engineering.Alternation_Clock_Hour, Minute:=Ext_MultiControl.EXT_Engineering.Alternation_Clock_Minute) AND Ext_MultiControl.EXT_Engineering.Alternation_Visible THEN	
					CASE GetDayOfWeek(In:=GetTime()) OF
					
				   	 	_MON://Mandag
							RE_Alternate.Clk:=Ext_MultiControl.EXT_Engineering.Alternation_Days[0];
							
						_TUE://Tirsdag
							RE_Alternate.Clk:=Ext_MultiControl.EXT_Engineering.Alternation_Days[1];
							
						_WED://Onsdag
							RE_Alternate.Clk:=Ext_MultiControl.EXT_Engineering.Alternation_Days[2];
							
						_THU://Torsdag
							RE_Alternate.Clk:=Ext_MultiControl.EXT_Engineering.Alternation_Days[3];

						_FRI://Fredag
							RE_Alternate.Clk:=Ext_MultiControl.EXT_Engineering.Alternation_Days[4];

						_SAT://Lørdag
							RE_Alternate.Clk:=Ext_MultiControl.EXT_Engineering.Alternation_Days[5];
							
						_SUN://Søndag
							RE_Alternate.Clk:=Ext_MultiControl.EXT_Engineering.Alternation_Days[6];
							
					END_CASE;
				ELSE
					RE_Alternate.Clk := FALSE;
				END_IF;

				RE_Alternate(Q=>Wrk_Alternernate);

				//Lager statusord for frekvensomformere basert på kriterier
				//---------------------------------------------------------------
				
				FOR Wrk_UpdateActuatorData_Index:=DINT_TO_UINT(LOWER_BOUND(Int_ActuatorData,1)) TO DINT_TO_UINT(UPPER_BOUND(Int_ActuatorData,1)) DO
					Wrk_ActuatorState[Wrk_UpdateActuatorData_Index]:=Int_ActuatorData[Wrk_UpdateActuatorData_Index].AvailableAuto;
				END_FOR;
				
				//Excecuting control block
				//---------------------------
				
				FB_ActuatorControl(ENS:=TRUE, 
												Inp_Block:=Wrk_ActionState = 1, //Action set to "Hold"
												Cmd_Alternate:=Wrk_Alternernate, 
												Cmd_StepIn:=Wrk_StepIn, 
												Cmd_StepOut:=Wrk_StepOut, 
												Cfg_NewOnLoss:=Ext_MultiControl.EXT_Engineering.Step_NewOnLoss, 
												Cfg_MinimumCount:=UINT_TO_USINT(Ext_MultiControl.EXT_Engineering.Step_MinimumCount), 
												Cfg_MaximumCount:=UINT_TO_USINT(Ext_MultiControl.EXT_Engineering.Step_MaximumCount), 
												Inp_State:=Wrk_ActuatorState, 
												Out_Start=>Wrk_ActuatorEngage, 
												Out_NumberOfReady=>Wrk_NumberOfReady, 
												Out_NumberOfRunning=>Wrk_NumberOfRunning);
				
				IF Wrk_ActionState = 3 THEN
					Clear(Wrk_ActuatorEngage);
				END_IF;

END_CASE;

(*************************************************************************
 *	STATISTIC DATA
 *************************************************************************)

RE_Minute(Clk:=Get1minClk());

IF RE_Minute.Q AND Ext_MultiControl.EXT_Operator.Mode = 2 THEN
	
	//Process value at setpoint
	IF Ext_MultiControl.EXT_Operator.SP_Actual.ProcessValue > Ext_MultiControl.EXT_Operator.PV_Actual.ProcessValue * 1.1 OR Ext_MultiControl.EXT_Operator.SP_Actual.ProcessValue < Ext_MultiControl.EXT_Operator.PV_Actual.ProcessValue * 0.9 THEN
		Inc(Ext_MultiControl.EXT_Statistics.TimeToday_AtSetpoint);
	//Prosess value under setpoint
	ELSIF Ext_MultiControl.EXT_Operator.SP_Actual.ProcessValue < Ext_MultiControl.EXT_Operator.PV_Actual.ProcessValue * 0.91 THEN
		Inc(Ext_MultiControl.EXT_Statistics.TimeToday_UnderSetpoint);
	//Prosess value over setpoint
	ELSIF Ext_MultiControl.EXT_Operator.SP_Actual.ProcessValue > Ext_MultiControl.EXT_Operator.PV_Actual.ProcessValue * 0.11 THEN
		Inc(Ext_MultiControl.EXT_Statistics.TimeToday_OverSetpoint);
	END_IF;
	
END_IF;

IF Sample_Day <> DateStruct.Day THEN
	Ext_MultiControl.EXT_Statistics.TimeToday_AtSetpoint := 0;
	Ext_MultiControl.EXT_Statistics.TimeToday_UnderSetpoint := 0;
	Ext_MultiControl.EXT_Statistics.TimeToday_OverSetpoint := 0;
	Sample_Day := DateStruct.Day;
END_IF;

(*************************************************************************
 *	OUTPUT AND STRUCTURE UPDATE
 *************************************************************************)
 
//Updating external structure
//-------------------------------
Ext_MultiControl.EXT_Operator.Manual_StepIn:=FALSE;
Ext_MultiControl.EXT_Operator.Manual_StepOut:=FALSE;
Ext_MultiControl.EXT_Engineering.Step_MaximumCount:=LIMIT(MN:=Ext_MultiControl.EXT_Engineering.Step_MinimumCount, In:=Ext_MultiControl.EXT_Engineering.Step_MaximumCount, MX:=UINT#16);
Ext_MultiControl.EXT_Engineering.Step_MinimumCount:=LIMIT(MN:=UINT#0, In:=Ext_MultiControl.EXT_Engineering.Step_MinimumCount, MX:=UINT#16);

//Updating outputs
//------------------------------
FOR Wrk_UpdateActuatorData_Index:=DINT_TO_UINT(LOWER_BOUND(Int_ActuatorData,1)) TO DINT_TO_UINT(UPPER_BOUND(Int_ActuatorData,1)) DO
	IF NOT Cfg_Mode THEN
		Int_ActuatorData[Wrk_UpdateActuatorData_Index].AutoReference:=	Ext_MultiControl.EXT_Operator.Actual_Output;
		Int_ActuatorData[Wrk_UpdateActuatorData_Index].AutoStart:=			Int_ActuatorData[Wrk_UpdateActuatorData_Index].AvailableAuto;
	ELSE
		Int_ActuatorData[Wrk_UpdateActuatorData_Index].AutoReference:=	Ext_MultiControl.EXT_Operator.Actual_Output;
		Int_ActuatorData[Wrk_UpdateActuatorData_Index].AutoStart:=			Wrk_ActuatorEngage[Wrk_UpdateActuatorData_Index];
	END_IF;
END_FOR;

Sts_Alarm:=				Wrk_AlarmTriggered;

//Updating internal structure
//------------------------------
Ext_MultiControl.INT_Data.NumberAvailable := Wrk_NumberOfReady;
Ext_MultiControl.INT_Data.NumberRunning 	:=	Wrk_NumberOfRunning;
